<?php require_once __DIR__.'/config/database.php';require_once __DIR__.'/config/auth.php';require_page('nursing.php');$page_title='Catatan Keperawatan';$page_subtitle=is_role('nurse')?'Dokumentasi asuhan keperawatan append-only: assessment, intervention, evaluation, pain dan fall risk.':'Review dokumentasi keperawatan tanpa hak mengubah catatan perawat.';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST' && is_role('nurse')){check_csrf();$pid=(int)($_POST['patient_id']??0);$eid=(int)($_POST['encounter_id']??0);$pain=(int)($_POST['pain_score']??0);if($pid<1||$pain<0||$pain>10||trim($_POST['assessment']??'')===''||trim($_POST['intervention']??'')===''||trim($_POST['evaluation']??'')===''){$msg='Lengkapi assessment, intervention, evaluation, dan pasien.';}else{$s=$pdo->prepare('INSERT INTO nursing_notes(patient_id,encounter_id,nurse_id,assessment,intervention,evaluation,fall_risk,pain_score,notes) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([$pid,$eid?:null,current_user_id(),trim($_POST['assessment']),trim($_POST['intervention']),trim($_POST['evaluation']),$_POST['fall_risk']??'low',$pain,trim($_POST['notes']??'')]);audit($pdo,'CREATE','NURSING',$pdo->lastInsertId(),'Catatan keperawatan dibuat dan bersifat append-only.');$msg='Catatan keperawatan berhasil disimpan.';}}
$patients=$pdo->query('SELECT id,mrn,name FROM patients ORDER BY name')->fetchAll();$notes=[];
if(is_role('doctor')){$s=$pdo->prepare("SELECT n.*,p.name patient,p.mrn,u.name nurse FROM nursing_notes n JOIN patients p ON p.id=n.patient_id JOIN users u ON u.id=n.nurse_id WHERE EXISTS(SELECT 1 FROM encounters e WHERE e.id=n.encounter_id AND e.doctor_id=?) ORDER BY n.recorded_at DESC LIMIT 50");$s->execute([doctor_id($pdo)]);$notes=$s->fetchAll();}
elseif(is_role('nurse')){$notes=$pdo->query("SELECT n.*,p.name patient,p.mrn,u.name nurse FROM nursing_notes n JOIN patients p ON p.id=n.patient_id JOIN users u ON u.id=n.nurse_id ORDER BY n.recorded_at DESC LIMIT 50")->fetchAll();}
else{$notes=$pdo->query("SELECT n.*,p.name patient,p.mrn,u.name nurse FROM nursing_notes n JOIN patients p ON p.id=n.patient_id JOIN users u ON u.id=n.nurse_id ORDER BY n.recorded_at DESC LIMIT 50")->fetchAll();}
include __DIR__.'/includes/header.php';?>
<?php if($msg):?><div class="alert <?=str_contains($msg,'berhasil')?'success':'danger'?>"><?=h($msg)?></div><?php endif;?>
<div class="grid two"><?php if(is_role('nurse')):?><div class="card"><div class="card-header"><div><h3 class="section-title">New Nursing Note</h3><p class="section-subtitle">Catatan tersimpan dengan author, timestamp, dan tidak dapat diedit oleh admin/dokter.</p></div></div><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><div class="form-grid"><div><label>Pasien</label><select name="patient_id" required><option value="">Pilih pasien</option><?php foreach($patients as $p):?><option value="<?=$p['id']?>"><?=h($p['mrn'].' — '.$p['name'])?></option><?php endforeach;?></select></div><div><label>Encounter ID (opsional)</label><input name="encounter_id" type="number" min="1" placeholder="ID encounter"></div><div><label>Fall Risk</label><select name="fall_risk"><option value="low">Low</option><option value="moderate">Moderate</option><option value="high">High</option></select></div><div><label>Pain Score (0–10)</label><input name="pain_score" type="number" min="0" max="10" value="0"></div></div><br><label>Assessment</label><textarea name="assessment" required placeholder="Kondisi umum, kesadaran, keluhan, fokus keperawatan..."></textarea><br><label>Intervention</label><textarea name="intervention" required placeholder="Monitoring, edukasi, tindakan, kolaborasi..."></textarea><br><label>Evaluation</label><textarea name="evaluation" required placeholder="Respons pasien terhadap intervensi..."></textarea><br><label>Catatan Tambahan</label><textarea name="notes"></textarea><button class="btn primary" style="margin-top:10px">Simpan Nursing Note</button></form></div><div class="card"><?php else:?><div class="card" style="grid-column:1/-1"><?php endif;?><div class="card-header"><div><h3 class="section-title">Nursing Notes</h3><p class="section-subtitle">Dokumentasi ditampilkan read-only untuk role selain perawat.</p></div><span class="tag"><?=count($notes)?> catatan</span></div><?php foreach($notes as $n):?><div class="timeline-item"><strong><?=h($n['patient'])?></strong> <span class="badge <?=$n['fall_risk']==='high'?'danger':($n['fall_risk']==='moderate'?'warn':'ok')?>">FALL <?=h(strtoupper($n['fall_risk']))?></span><div class="mini"><?=h(date('d/m/Y H:i',strtotime($n['recorded_at'])))?> · <?=h($n['nurse'])?> · pain <?=$n['pain_score']?>/10</div><p><b>Assessment:</b> <?=nl2br(h($n['assessment']))?></p><p><b>Intervention:</b> <?=nl2br(h($n['intervention']))?></p><p><b>Evaluation:</b> <?=nl2br(h($n['evaluation']))?></p><?php if($n['notes']):?><p class="mini"><b>Note:</b> <?=nl2br(h($n['notes']))?></p><?php endif;?></div><?php endforeach;?><?php if(!$notes):?><div class="empty"><strong>Belum ada catatan</strong><p>Dokumentasi keperawatan akan muncul setelah perawat menyimpan assessment pertama.</p></div><?php endif;?></div></div><?php include __DIR__.'/includes/footer.php';?>